/**
 * Attribution for a recipe photo.
 *
 * Recipe photos come from three places: real dish photos from
 * Wikipedia/Wikimedia (CC-licensed — attribution is required), images
 * generated by Pollinations.AI, and URLs pasted by the recipe author.
 * The server records the source on the recipe at write time
 * (`imageSource`), before the image cache rewrites the URL to a local
 * path. For older recipes without a recorded source, the origin is
 * derived from the image URL host; a cached local path carries no
 * origin, so it gets a generic note instead.
 */
export interface ImageAttribution {
  /** Short caption shown under the photo. */
  label: string;
  /** Link for the source name, when there is one. */
  href?: string;
}

const WIKIMEDIA_HOSTS = ['upload.wikimedia.org', 'commons.wikimedia.org', 'en.wikipedia.org'];

function sourceFromUrl(imageUrl?: string): 'wikimedia' | 'pollinations' | 'user' | 'cached' | undefined {
  if (!imageUrl) return undefined;
  if (imageUrl.startsWith('/static/') || imageUrl.startsWith('/')) return 'cached';
  let host: string;
  try {
    host = new URL(imageUrl).hostname.toLowerCase();
  } catch {
    return undefined;
  }
  if (WIKIMEDIA_HOSTS.includes(host)) return 'wikimedia';
  if (host === 'image.pollinations.ai') return 'pollinations';
  return 'user';
}

export function getImageAttribution(
  imageUrl?: string,
  imageSource?: 'wikimedia' | 'pollinations' | 'user'
): ImageAttribution | null {
  const source = imageSource ?? sourceFromUrl(imageUrl);
  switch (source) {
    case 'wikimedia':
      return {
        label: 'Photo: Wikimedia Commons (CC BY-SA)',
        href: 'https://commons.wikimedia.org',
      };
    case 'pollinations':
      return {
        label: 'Image generated by Pollinations.AI',
        href: 'https://pollinations.ai',
      };
    case 'cached':
      return {
        label: 'Photo cached by MealMate — see Attributions for image sources',
        href: '/attributions',
      };
    case 'user':
    default:
      return null;
  }
}
